fn:
// One open footnote at a time (reader text): close every open note except keep.
function closeOpenFootnotes(keep) {
  document.querySelectorAll('.reader-footnote.open').forEach(n => {
    if (n === keep) return;
    n.classList.remove('open');
    document.querySelectorAll('.footnote-marker[aria-expanded="true"]').forEach(m => {
      if (m.dataset.fn === n.dataset.fn && (!n.dataset.noteKey || m.dataset.noteKey === n.dataset.noteKey)) m.setAttribute('aria-expanded', 'false');
    });
  });
}
